#define IN0_CLKON       0x0
#define IN1_CLKON       0x1
#define IN2_CLKON       0x2
#define IN3_CLKON       0x3

#define CDU_CLKO0       0x0
#define CDU_CLKO1       0x1
#define CDU_CLKO2       0x2
#define CDU_CLKO3       0x3
#define CDU_CLKO4       0x4
#define CDU_CLKO5       0x5
#define CDU_CLKO6       0x6
#define CDU_CLKO7       0x7
#define CDU_CLKO8       0x8
#define CDU_CLKO9       0x9
#define CDU_CLKO10      0xA
#define CDU_CLKO12      0xC
#define CDU_CLKO13      0xD
#define CDU_CLKO14      0xE

#define PDATA(_name)	\
	static const struct clk_parent_data _name[]

#define MUX_TABLE(_name)	\
	static const u32 _name[]

#define ADSP_CDU_CLK_FLAGS	\
	(CLK_SET_RATE_PARENT | CLK_OPS_PARENT_ENABLE)

#define ADSP_CDU_CLK_FLAGS_CRITICAL	\
	(ADSP_CDU_CLK_FLAGS | CLK_IS_CRITICAL)

#define ADSP_CDU_CFG(n)		((n) * sizeof(u32))

#define ADSP_CDU_LOCK		BIT(31)

#define ADSP_CDU_CLKINSEL	0x44
#define ADSP_CDU_CLKINSEL_CGU1	BIT(0)

#define ADSP_CDU_STAT		0x40
#define ADSP_CDU_STAT_LWERR	BIT(17)
#define ADSP_CDU_STAT_ADRERR	BIT(16)

#define ADSP_CDU_CFG_EN		BIT(0)
#define ADSP_CDU_CFG_SEL	GENMASK(2, 1)

#define ADSP_CDU_REVID		0x48
#define ADSP_CDU_REVID_MAJOR	GENMASK(7, 4)
#define ADSP_CDU_REVID_REV	GENMASK(3, 0)

#define ADSP_CDU_POLL_DELAY	5
#define ADSP_CDU_POLL_TIMEOUT	50

/**
 * struct adsp_cdu_clks - information about cdu clock
 * @parent_data: parent clock descriptions used by CCF
 * @mux_table: input clock SEL table for this clock
 * @clock_name: name of this clock
 * @clock_flags: common clock framework flags for this clock
 * @id: clock provider onecell identifier
 * @cdu_clko: the CDU CLKO bit
 * @num_parents: number of entries in @parent_data
 */
struct adsp_cdu_clks {
	const struct clk_parent_data	*parent_data;
	const u32			*mux_table;
	const char			*clock_name;
	unsigned long			clock_flags;
	unsigned int			id;
	u8				cdu_clko;
	u8				num_parents;
};

#define CDU(_id, _parents, _mux, _name, _flags, _clko)	\
	{							\
		.id		= _id,				\
		.parent_data	= _parents,			\
		.mux_table	= _mux,				\
		.clock_name	= _name,			\
		.clock_flags	= _flags,			\
		.cdu_clko	= _clko,			\
		.num_parents	= ARRAY_SIZE(_parents),		\
	}

/**
 * struct adsp_cdu_match_data - SoC specific CDU clock data
 * @clks: array of CDU clock descriptions for the SoC
 * @num_clks: number of entries in @clks
 * @reserved_mask: mask of non configurable CDU outputs
 * @has_clkin: indication if CDU has CLKINSEL clock
 */
struct adsp_cdu_match_data {
	const struct adsp_cdu_clks	*clks;
	unsigned int			num_clks;
	unsigned int			reserved_mask;
	bool				has_clkin;
};

/* CDU CLKOn input clock source configurations */
MUX_TABLE(CDU_CLKO_SEL1)	= { IN0_CLKON };
MUX_TABLE(CDU_CLKO_SEL2)	= { IN1_CLKON };
MUX_TABLE(CDU_CLKO_SEL3)	= { IN0_CLKON, IN1_CLKON };
MUX_TABLE(CDU_CLKO_SEL4)	= { IN0_CLKON, IN1_CLKON, IN2_CLKON };
MUX_TABLE(CDU_CLKO_SEL5)	= { IN0_CLKON, IN2_CLKON, IN3_CLKON };
MUX_TABLE(CDU_CLKO_SEL6)	= { IN0_CLKON, IN1_CLKON, IN2_CLKON, IN3_CLKON };

